Condition::HasId(has_id) => {
    let segment_ids: AHashSet<_> = has_id
        .has_id
        .iter()
        .filter_map(|external_id| id_tracker.internal_id(*external_id))
        .collect();
    Box::new(move |point_id| segment_ids.contains(&point_id))
}

